import{_ as i,l as o,o as e,c as s,v as t,p as n,x as r,d as p,i as d,S as h}from"./chunks/framework.InCnrqk-.js";const D=JSON.parse('{"title":"锁存与触发器","description":"","frontmatter":{"title":"锁存与触发器","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/latch-flipflop.md","filePath":"cs/latch-flipflop.md","lastUpdated":1789023840000}'),c={name:"cs/latch-flipflop.md"};function F(E,a,f,_,A,m){const l=o("Mermaid");return e(),s("div",null,[a[1]||(a[1]=t('<h1 id="锁存与触发器" tabindex="-1">锁存与触发器 <a class="header-anchor" href="#锁存与触发器" aria-label="Permalink to &quot;锁存与触发器&quot;">​</a></h1><div class="epigraph"><p>组合网没有记忆；要让比特在时钟拍之间还在，必须用交叉耦合或边沿采样把状态关进回路里。</p><footer>—— 据 Harris and Harris, Digital Design and Computer Architecture 整理</footer></div><p>上一课<a href="/cs/pla-rom">PLA 与 ROM 作组合</a>把组合算术收到「三种比较」。本课不重接线旗标，也不从操作系统进程另起。缺口是：到现在所有块都是 \\(y=f(x)\\)。计数器、寄存器、后课 PC，需要 \\(y\\) 依赖<strong>过去</strong>。数字逻辑在这里进入时序：锁存与触发器。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>组合反馈可以振荡或进入亚稳，不能当受控记忆。缺口是受控存储元件：电平敏感的 <strong>D 锁存</strong>在时钟高（或低）时透明、否则保持；边沿敏感的 <strong>D 触发器</strong>只在上升沿（或下降沿）把 D 送入 Q。后课同步设计默认触发器，避免透明造成的环路同时导通。</p><p>SRAM 单元也是交叉耦合，但是阵列课的对象；本课只钉 1 比特的锁存/FF。</p><h3 id="锁存不是触发器" tabindex="-1">锁存不是触发器 <a class="header-anchor" href="#锁存不是触发器" aria-label="Permalink to &quot;锁存不是触发器&quot;">​</a></h3><p>教科书与口语常把 flip-flop 与 latch 混用。本栏：latch 电平透明，FF 边沿。用两个锁存主从可以拼成 FF。把锁存当 FF 用在同一时钟上，保持时间与环路会一起坏。</p><p><span class="marginnote">Harris 用时序图区分透明窗与边沿。本课不把 JK、T 触发器当主干：它们可由 D 与组合构成。异步置位清零当端口承认，不展开异步状态机。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>SR 交叉耦合：禁止 \\(S=R=1\\) 的那种。D 锁存：时钟选通，透明时 \\(Q=D\\)。主从：前级锁存在时钟一半透明，后级在另一半，整体边沿。触发器输出 Q 在周期内除边沿外保持。</p>',11)),(e(),n(h,null,{default:r(()=>[d(l,{id:"mermaid-31",class:"mermaid",graph:"flowchart%20TD%0A%20%20COMB%5B%22%E7%BB%84%E5%90%88%20y%3Df(x)%22%5D%20--%3E%20LAT%5B%22D%20%E9%94%81%E5%AD%98%EF%BC%9A%E9%80%8F%E6%98%8E%E7%AA%97%22%5D%0A%20%20LAT%20--%3E%20FF%5B%22%E8%BE%B9%E6%B2%BF%20D%20%E8%A7%A6%E5%8F%91%E5%99%A8%22%5D%0A%20%20FF%20--%3E%20LATER%5B%22%E5%90%8E%E8%AF%BE%EF%BC%9A%E5%BB%BA%E7%AB%8B%E4%B8%8E%E4%BF%9D%E6%8C%81%22%5D%0A"})]),fallback:r(()=>[...a[0]||(a[0]=[p(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=t('<h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>有了 FF，才能切出「周期」：周期内组合计算，边沿更新状态。后课寄存器是并排 FF；FSM 的现态是一组 FF。时钟尚未多域，本课假设单时钟理想边沿。亚稳态：若 D 在边沿附近变，Q 可能长时间不合法——量化是下一课建立保持。复位可以同步接到 D 的 MUX，也可以异步进 FF 端口；主干默认同步复位，避免与时钟竞争。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不讲 PLL、不把 DRAM 电容当 FF。不引入多时钟。组合逻辑险象若打在锁存透明窗里会被放行；FF 只采样边沿附近。</p><p>后课默认：同步状态存在边沿 D 触发器里；锁存仅在明确的透明协议里使用。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>记忆需要锁存或触发器；组合反馈不是受控状态。</li><li>锁存电平透明；FF 边沿采样。</li><li>时序约束（建立/保持）下一课才写成不等式。</li><li>主干默认同步复位，避免异步端口与时钟竞争。</li><li>出处：Harris and Harris。</li></ul>',7))])}const B=i(c,[["render",F]]);export{D as __pageData,B as default};
